    from collections import defaultdict, deque

    # Create adjacency list and in-degree count
    adj_list = defaultdict(list)
    in_degree = [0] * (N + 1)
    for x, y in edges:
        adj_list[x].append(y)
        in_degree[y] += 1

    # Topological sort to find the order of nodes
    queue = deque()
